const el=id=>document.getElementById(id);let token='',epoch=0;
async function api(options={}){const r=await fetch('/api/admin/recruitment',{...options,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function load(){const current=++epoch;const {items}=await api();if(current!==epoch||!token)return;el('rows').replaceChildren();for(const item of items){const section=document.createElement('section'),title=document.createElement('h2'),details=document.createElement('p');title.textContent=item.nom;details.textContent=item.email+' — '+item.message;section.append(title,details);if(item.consultant_id){const a=document.createElement('a');a.href='consultants.html';a.textContent='Profil qualifié — ouvrir le vivier';section.append(a)}else{const f=document.createElement('form');for(const [name,label,max] of [['role','Métier',120],['skills','Compétences',1000]]){const l=document.createElement('label'),input=document.createElement('input');l.textContent=label;input.name=name;input.maxLength=max;input.required=true;l.append(input);f.append(l)}const b=document.createElement('button');b.textContent='Qualifier dans le vivier';f.append(b);f.onsubmit=async e=>{e.preventDefault();b.disabled=true;try{await api({method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(f)),request_id:item.id})});await load();el('notice').textContent='Qualification enregistrée.'}catch(e){el('notice').textContent=e.message}finally{b.disabled=false}};section.append(f)}el('rows').append(section)}if(!items.length)el('rows').textContent='Aucune candidature.'}
el('login-form').onsubmit=async e=>{e.preventDefault();token=el('token').value;el('token').value='';try{await load();el('login').hidden=true;el('workspace').hidden=false}catch(e){token='';el('notice').textContent=e.message}};
el('logout').onclick=()=>{epoch++;token='';el('rows').replaceChildren();el('workspace').hidden=true;el('login').hidden=false};
